import unittest
from flags import normalize_flag
class Contract(unittest.TestCase):
    def test_false(self): self.assertFalse(normalize_flag("false"))
    def test_trim(self): self.assertTrue(normalize_flag(" TRUE "))
    def test_boolean(self): self.assertFalse(normalize_flag(False))
    def test_invalid(self):
        for value in [None, 1, "no"]:
            with self.assertRaises(ValueError): normalize_flag(value)

